43	/**
44	 * Get the effective request options for MCP requests.
45	 * Priority: config values > MCP_REQUEST_TIMEOUT_MS env var > undefined (SDK default of 60s)
46	 */
47	function getEffectiveRequestOptions(config: MCPConfig): MCPRequestOptions | undefined {
48	  const timeout = config.timeout ?? getEnvInt('MCP_REQUEST_TIMEOUT_MS');
49	
50	  // If no timeout options are set, return undefined to use SDK defaults
51	  if (!timeout && !config.resetTimeoutOnProgress && !config.maxTotalTimeout) {
52	    return undefined;
53	  }
54	
55	  const options: MCPRequestOptions = {};
56	
57	  if (timeout) {
58	    options.timeout = timeout;
59	  }
60	
61	  if (config.resetTimeoutOnProgress) {
62	    options.resetTimeoutOnProgress = config.resetTimeoutOnProgress;
63	  }
64	
65	  if (config.maxTotalTimeout) {
66	    options.maxTotalTimeout = config.maxTotalTimeout;
67	  }
68	
69	  return options;
70	}
