19	export class MCPProvider implements ApiProvider {
20	  private mcpClient: MCPClient;
21	  config: MCPConfig;
22	  private defaultArgs?: Record<string, unknown>;
23	  private initializationPromise: Promise<void>;
24	
25	  constructor(options: MCPProviderOptions = {}) {
26	    this.config = options.config || { enabled: true };
27	    this.defaultArgs = options.defaultArgs || {};
28	
29	    this.mcpClient = new MCPClient(this.config);
30	    this.initializationPromise = this.initialize();
31	
32	    // Set id function if provided
33	    if (options.id) {
34	      this.id = () => options.id!;
35	    }
36	  }
37	
38	  id(): string {
39	    return 'mcp';
40	  }
41	
42	  toString(): string {
43	    return `[MCP Provider]`;
44	  }
45	
46	  private async initialize(): Promise<void> {
47	    await this.mcpClient.initialize();
48	
49	    if (this.config.verbose) {
50	      const tools = this.mcpClient.getAllTools();
51	      console.log(
52	        'MCP Provider initialized with tools:',
53	        tools.map((t) => t.name),
54	      );
55	    }
56	  }
57	
58	  async callApi(
59	    prompt: string,
60	    context?: CallApiContextParams,
61	    _options?: CallApiOptionsParams,
62	  ): Promise<ProviderResponse> {
63	    try {
64	      // Ensure initialization is complete
65	      await this.initializationPromise;
66	
67	      // Parse the prompt as JSON to extract tool call information
68	      let toolCallData: any;
69	      try {
70	        const rawToolCall = context?.vars?.prompt ?? prompt;
71	        toolCallData = JSON.parse(String(rawToolCall));
72	      } catch {
73	        return {
74	          error:
75	            'Invalid JSON in prompt. MCP provider expects a JSON payload with tool call information.',
76	        };
77	      }
78	
79	      // Extract tool name from various possible fields
80	      const toolName =
81	        toolCallData.tool ||
82	        toolCallData.toolName ||
83	        toolCallData.function ||
84	        toolCallData.functionName ||
85	        toolCallData.name;
86	
87	      if (!toolName || typeof toolName !== 'string') {
88	        return {
89	          error:
90	            'No tool name found in JSON payload. Expected format: {"tool": "function_name", "args": {...}}',
91	        };
92	      }
93	
94	      // Extract tool arguments from various possible fields
95	      let toolArgs =
96	        toolCallData.args ||
97	        toolCallData.arguments ||
98	        toolCallData.params ||
99	        toolCallData.parameters ||
100	        {};
101	
102	      // Ensure toolArgs is an object
103	      if (typeof toolArgs !== 'object' || toolArgs === null || Array.isArray(toolArgs)) {
104	        toolArgs = {};
105	      }
106	
107	      // Merge with default args
108	      const finalArgs = {
109	        ...this.defaultArgs,
110	        ...toolArgs,
111	      };
112	
113	      logger.debug(`MCP Provider calling tool ${toolName} with args: ${JSON.stringify(finalArgs)}`);
114	
115	      // Call the MCP tool
116	      const result = await this.mcpClient.callTool(toolName, finalArgs);
117	
118	      if (result.error) {
119	        return {
120	          error: `MCP tool error: ${result.error}`,
121	          raw: result,
122	        };
123	      }
124	
125	      return {
126	        output: result.content,
127	        raw: result,
128	        metadata: {
129	          toolName,
130	          toolArgs: finalArgs,
131	          originalPayload: toolCallData,
132	        },
133	      };
134	    } catch (error) {
135	      const errorMessage = error instanceof Error ? error.message : String(error);
136	      logger.error(`MCP Provider error: ${errorMessage}`);
137	      return {
138	        error: `MCP Provider error: ${errorMessage}`,
139	      };
140	    }
141	  }
142	
143	  async cleanup(): Promise<void> {
144	    try {
145	      await this.mcpClient.cleanup();
146	    } catch (error) {
147	      logger.error(
148	        `Error during MCP provider cleanup: ${error instanceof Error ? error.message : String(error)}`,
149	      );
150	    }
151	  }
