153	  // Method to call specific MCP tools directly
154	  async callTool(toolName: string, args: Record<string, unknown>): Promise<ProviderResponse> {
155	    try {
156	      await this.initializationPromise;
157	
158	      const result = await this.mcpClient.callTool(toolName, args);
159	
160	      if (result.error) {
161	        return {
162	          error: `MCP tool error: ${result.error}`,
163	        };
164	      }
165	
166	      return {
167	        output: result.content,
168	        raw: result,
169	      };
170	    } catch (error) {
171	      const errorMessage = error instanceof Error ? error.message : String(error);
172	      return {
173	        error: `MCP tool call error: ${errorMessage}`,
174	      };
175	    }
176	  }
177	
178	  // Get all available tools
179	  async getAvailableTools() {
180	    await this.initializationPromise;
181	
182	    return this.mcpClient.getAllTools();
183	  }
184	
185	  // Get connected servers
186	  getConnectedServers() {
187	    return this.mcpClient.connectedServers;
188	  }
189	}
