28	export function transformMCPToolsToOpenAi(tools: MCPTool[]): OpenAiTool[] {
29	  return tools.map((tool) => {
30	    const schema: MCPToolInputSchema = tool.inputSchema;
31	    let properties: Record<string, any> = {};
32	    let required: string[] | undefined = undefined;
33	    let additionalProperties: boolean | Record<string, any> | undefined = undefined;
34	
35	    if (schema && typeof schema === 'object' && 'properties' in schema) {
36	      // Extract properties and required fields from the schema
37	      properties = schema.properties ?? {};
38	      required = schema.required;
39	
40	      // Preserve additionalProperties if it exists
41	      if ('additionalProperties' in schema) {
42	        additionalProperties = schema.additionalProperties;
43	      }
44	    } else if (schema && typeof schema === 'object') {
45	      // Schema exists but doesn't have properties field
46	      // This shouldn't normally happen with MCP SDK, but handle it gracefully
47	      properties = {};
48	    } else {
49	      // No schema or invalid schema
50	      properties = {};
51	    }
52	
53	    return {
54	      type: 'function',
55	      function: {
56	        name: tool.name,
57	        description: tool.description,
58	        parameters: {
59	          type: 'object',
60	          properties,
61	          ...(required && required.length > 0 ? { required } : {}),
62	          ...(additionalProperties === undefined ? {} : { additionalProperties }),
63	        },
64	      },
65	    };
66	  });
67	}
