84	export function transformMCPToolsToGoogle(tools: MCPTool[]): GoogleTool[] {
85	  const functionDeclarations: GoogleFunctionDeclaration[] = tools.map((tool) => {
86	    const schema: MCPToolInputSchema = tool.inputSchema;
87	    let parameters: GoogleSchema;
88	
89	    if (schema && typeof schema === 'object') {
90	      // Sanitize schema for Gemini compatibility:
91	      // - Removes unsupported properties (additionalProperties, $schema, default, etc.)
92	      // - Converts types to uppercase (string → STRING)
93	      // - Recursively processes nested schemas
94	      parameters = sanitizeSchemaForGemini(schema) as GoogleSchema;
95	
96	      // Ensure type is OBJECT at root level for function parameters
97	      if (!parameters.type) {
98	        parameters.type = 'OBJECT';
99	      }
100	
101	      // Ensure properties exists
102	      if (!parameters.properties) {
103	        parameters.properties = {};
104	      }
105	    } else {
106	      parameters = { type: 'OBJECT', properties: {} };
107	    }
108	
109	    return {
110	      name: tool.name,
111	      description: tool.description,
112	      parameters,
113	    };
114	  });
115	  return [{ functionDeclarations }];
116	}
