/**
 * Normalizes the result of a response transform into a {@link ProviderResponse}.
 *
 * If the value is already a ProviderResponse-like object (a non-null, non-array
 * object containing an `output` or `error` property), it is returned unchanged.
 * Otherwise the value is wrapped as `{ output: value }`.
 *
 * @param value - The value returned by a response transform.
 * @returns A ProviderResponse.
 */
export function normalizeResponseTransformResult(value: unknown): ProviderResponse {
  if (
    value != null &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    ('output' in value || 'error' in value)
  ) {
    return value as ProviderResponse;
  }
  return { output: value };
}
