import cliState from '../cliState';
import { importModule } from '../esm';
import { isJavascriptFile } from '../util/fileExtensions';

/**
 * Parses a `file://` reference string into a filename and an optional named export.
 *
 * The reference is split on the LAST colon to separate the filename from an optional
 * named export (`functionName`). Windows paths (e.g. `C:\path\parser.js`) are handled
 * correctly by only treating the trailing segment as a named export when the preceding
 * segment is recognized as a JavaScript file — this prevents the Windows drive-letter
 * colon from being mistaken for a named-export separator.
 *
 * @param reference - A `file://` reference (the `file://` prefix is optional).
 * @returns An object with the `filename` and an optional `functionName`.
 */
export function parseFileTransformReference(reference: string): {
  filename: string;
  functionName?: string;
} {
  const withoutPrefix = reference.startsWith('file://')
    ? reference.slice('file://'.length)
    : reference;

  const lastColonIndex = withoutPrefix.lastIndexOf(':');
  if (lastColonIndex !== -1) {
    const candidateFilename = withoutPrefix.slice(0, lastColonIndex);
    const candidateFunctionName = withoutPrefix.slice(lastColonIndex + 1);
    if (candidateFilename && isJavascriptFile(candidateFilename)) {
      return { filename: candidateFilename, functionName: candidateFunctionName };
    }
  }

  return { filename: withoutPrefix };
}

/**
 * Pre-loads a transform from a `file://` reference by resolving the filename relative to
 * {@link cliState.basePath} and importing the module.
 *
 * - If the transform is a `file://` reference, the resolved module must be a function;
 *   otherwise this throws.
 * - For non-file transforms (functions or plain string expressions), the input is
 *   returned unchanged.
 *
 * @param transform - The transform config (string, function, or undefined).
 * @returns The loaded function, or the original value if not a `file://` reference.
 */
export async function loadTransformModule(
  transform: string | Function | undefined,
): Promise<string | Function | undefined> {
  if (!transform) {
    return transform;
  }
  if (typeof transform === 'function') {
    return transform;
  }
  if (typeof transform === 'string' && transform.startsWith('file://')) {
    const { filename, functionName } = parseFileTransformReference(transform);
    const requiredModule = await importModule(
      path.resolve(cliState.basePath || '', filename),
      functionName,
    );
    if (typeof requiredModule === 'function') {
      return requiredModule;
    }
    throw new Error(
      `Transform module malformed: ${filename} must export a function or have a default export as a function`,
    );
  }
  // For string expressions, return as-is
  return transform;
}
