import { normalizeResponseTransformResult } from '../transformResult';

import type { ProviderResponse } from '../../types/index';

/**
 * Context passed to MCP response transforms describing the tool call.
 */
export interface MCPTransformResponseContext {
  toolName: string;
  toolArgs: Record<string, unknown>;
  originalPayload?: unknown;
}

/**
 * Factory that creates a response transform for MCP tool results.
 *
 * - When `parser` is undefined, returns a transform that produces `{ output: content }`.
 * - When `parser` is a function (sync or async), calls it with `(result, content, context)`,
 *   awaits the return value, and normalizes it via {@link normalizeResponseTransformResult}.
 * - When `parser` is a JavaScript expression string, evaluates it with `result`, `content`,
 *   and `context` in scope, awaits the result, and normalizes it. Evaluation errors are
 *   wrapped in a new error whose message starts with "Failed to transform MCP response".
 * - When `parser` is a `file://` string, throws synchronously (file references must be
 *   pre-loaded before calling this function).
 * - When `parser` is any other type, throws.
 *
 * Note: `file://` references should be pre-loaded using `loadTransformModule` before being
 * passed to this function. This mirrors the HTTP provider so the transform can be tested in
 * the UI (which cannot use `importModule`).
 */
export function createTransformResponse(
  parser: string | Function | undefined,
): (
  result: unknown,
  content: string,
  context: MCPTransformResponseContext,
) => Promise<ProviderResponse> {
  if (!parser) {
    return async (_result, content) => ({ output: content });
  }

  if (typeof parser === 'function') {
    return async (result, content, context) => {
      const value = await parser(result, content, context);
      return normalizeResponseTransformResult(value);
    };
  }

  if (typeof parser === 'string' && parser.startsWith('file://')) {
    // This should have been pre-loaded using loadTransformModule.
    throw new Error(
      `Response transform with file:// reference should be pre-loaded before calling createTransformResponse. This is a bug in the MCP provider implementation.`,
    );
  }

  if (typeof parser === 'string') {
    return async (result, content, context) => {
      try {
        const trimmedParser = parser.trim();
        // Check if it's a function expression (either arrow or regular)
        const isFunctionExpression = /^(\(.*?\)\s*=>|function\s*\(.*?\))/.test(trimmedParser);
        // Add process parameter for ESM compatibility - allows process.mainModule.require to work
        const transformFn = new Function(
          'result',
          'content',
          'context',
          'process',
          isFunctionExpression
            ? `return (${trimmedParser})(result, content, context);`
            : `return (${trimmedParser});`,
        );
        const processShim = getProcessShim();
        const value = await transformFn(result, content, context, processShim);
        return normalizeResponseTransformResult(value);
      } catch (err) {
        throw new Error(`Failed to transform MCP response: ${String(err)}`);
      }
    };
  }

  throw new Error(
    `Unsupported response transform type: ${typeof parser}. Expected a function, a string starting with 'file://' pointing to a JavaScript file, or a string containing a JavaScript expression.`,
  );
}
